module WatchLaterMinClicks (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] video_types [0:15],\n    input wire [4:0] length,\n    output reg [7:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] STATE_IDLE         = 3'd0;\n    localparam [2:0] STATE_COUNT_SEG    = 3'd1;\n    localparam [2:0] STATE_FIND_MIN     = 3'd2;\n    localparam [2:0] STATE_REMOVE_TYPE  = 3'd3;\n    localparam [2:0] STATE_UPDATE_RES   = 3'd4;\n    localparam [2:0] STATE_DONE         = 3'd5;\n    \n    reg [2:0] state;\n    reg [2:0] next_state;\n    \n    // Data storage\n    reg [7:0] current_videos [0:15];\n    reg [4:0] current_length;\n    \n    // Working registers\n    reg [7:0] segments [0:7];\n    reg [7:0] min_segment_count;\n    reg [2:0] min_segment_type;\n    reg [3:0] type_iterator;\n    reg [4:0] video_iterator;\n    reg [7:0] temp_result;\n    reg [4:0] removal_counter;\n    \n    // Helper function: ASCII to type index\n    function [2:0] char_to_type(input [7:0] c);\n        begin\n            char_to_type = c[2:0];  // Use lower 3 bits \n        end\n    endfunction\n    \n    // Helper function: type exists in video list\n    function type_exists(input [2:0] t);\n        integer i;\n        begin\n            type_exists = 1'b0;\n            for (i = 0; i < current_length; i = i + 1) begin\n                if (char_to_type(current_videos[i]) == t) begin\n                    type_exists = 1'b1;\n                end\n            end\n        end\n    endfunction\n    \n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize all registers\n            state <= STATE_IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n            current_length <= 5'd0;\n            temp_result <= 8'd0;\n            \n            for (integer i = 0; i < 16; i = i + 1) begin\n                current_videos[i] <= 8'd0;\n            end\n            \n            for (integer j = 0; j < 8; j = j + 1) begin\n                segments[j] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                STATE_IDLE: begin\n                    done <= 1'b0;\n                    temp_result <= 8'd0;\n                    if (start) begin\n                        // Load video data\n                        current_length <= length;\n                        for (integer i = 0; i < 16; i = i + 1) begin\n                            if (i < length) \n                                current_videos[i] <= video_types[i];\n                            else\n                                current_videos[i] <= 8'd0;\n                        end\n                        state <= STATE_COUNT_SEG;\n                    end\n                end\n                \n                STATE_COUNT_SEG: begin\n                    // Reset segments\n                    for (integer j = 0; j < 8; j = j + 1) begin\n                        segments[j] <= 8'd0;\n                    end\n                    \n                    // Count segments (per type)\n                    video_iterator <= 5'd0;\n                    state <= STATE_COUNT_SEG_LOOP;\n                end\n                \n                STATE_COUNT_SEG_LOOP: begin\n                    if (video_iterator < current_length) begin\n                        if (video_iterator == 0) begin\n                            segments[char_to_type(current_videos[0])] <= 8'd1;\n                        end else begin\n                            if (char_to_type(current_videos[video_iterator]) != \n                                char_to_type(current_videos[video_iterator-1])) begin\n                                segments[char_to_type(current_videos[video_iterator])] <= \n                                    segments[char_to_type(current_videos[video_iterator])] + 8'd1;\n                            end\n                        end\n                        video_iterator <= video_iterator + 5'd1;\n                    end else begin\n                        state <= STATE_FIND_MIN;\n                        type_iterator <= 3'd0;\n                        min_segment_count <= 8'hFF;  // Max value\n                        min_segment_type <= 3'd0;\n                    end\n                end\n                \n                STATE_FIND_MIN: begin\n                    if (type_iterator < 3'd7) begin\n                        if (segments[type_iterator] != 0 && type_exists(type_iterator)) begin\n                            if (segments[type_iterator] < min_segment_count) begin\n                                min_segment_count <= segments[type_iterator];\n                                min_segment_type <= type_iterator;\n                            end\n                        end\n                        type_iterator <= type_iterator + 3'd1;\n                    end else begin\n                        if (min_segment_count == 8'hFF) begin\n                            // No segments found (shouldn't happen)\n                            state <= STATE_DONE;\n                        end else begin\n                            state <= STATE_REMOVE_TYPE;\n                            video_iterator <= 5'd0;\n                            removal_counter <= 5'd0;\n                        end\n                    end\n                end\n                \n                STATE_REMOVE_TYPE: begin\n                    if (video_iterator < current_length) begin\n                        if (char_to_type(current_videos[video_iterator]) == min_segment_type) begin\n                            // Shift later elements left\n                            for (integer i = video_iterator - removal_counter; i < current_length - 1; i = i + 1) begin\n                                current_videos[i] <= current_videos[i + 1];\n                            end\n                            removal_counter <= removal_counter + 5'd1;\n                        end\n                        video_iterator <= video_iterator + 5'd1;\n                    end else begin\n                        current_length <= current_length - removal_counter;\n                        state <= STATE_UPDATE_RES;\n                    end\n                end\n                \n                STATE_UPDATE_RES: begin\n                    temp_result <= temp_result + min_segment_count;\n                    if (current_length == removal_counter) begin\n                        state <= STATE_DONE;\n                    end else begin\n                        state <= STATE_COUNT_SEG;\n                    end\n                end\n                \n                STATE_DONE: begin\n                    result <= temp_result;\n                    done <= 1'b1;\n                    state <= STATE_IDLE;\n                end\n                \n                default: state <= STATE_IDLE;\n            endcase\n        end\n    end\n\nendmodule